//! `vuo-shim`: Qt-facing half of Vuo.
//!
//! Exists only to make [`vuo_core`] visible to QML. No application logic: no
//! sync policy, parsing, conflict resolution. Anything here making a decision
//! belongs in core, testable without Qt.
//!
//! # `unsafe` here, only here
//!
//! §9.5: `#![forbid(unsafe_code)]` in `vuo-core`, `unsafe` confined to this
//! crate, *"where `qmetaobject` requires it, and reviewed line by line"*.
//! Nearly all generated by `QObject` derive and `cpp!` macro. Exactly ONE
//! hand-written `unsafe` block, named so a second must be argued for:
//! [`memory`] calls glibc `malloc_trim` to return sync's freed peak to kernel.
//! Reviewed in place.
//!
//! # Registration, not application ownership
//!
//! [`register_qml_types`] registers types, returns. No `QmlEngine`:
//! `QmlEngine::new()` builds **`QtWidgets`** `QApplication`, wrong for Silica;
//! Sailfish needs `SailfishApp::application()` and `SailfishApp::createView()`
//! for Wayland, booster, theme setup. `qml_register_type` needs no engine:
//! Sailfish binary owns application, calls in here to register.
//!
//! # Qt 5.6 constraints
//!
//! `qmetaobject` build script emits `qt_5_7`..`qt_5_15` cfgs, nothing for 5.6:
//! on Sailfish target **`qml_register_enum`, `qml_register_module`,
//! `qml_register_singleton_instance` don't exist**. Enums cross into QML as
//! plain integers (see [`models::Scope::from_qml`]) and strings, not registered
//! types.

// QML-visible members camelCase on purpose.
//
// `qmetaobject` emits property, method, signal names VERBATIM (no snake→camel
// conversion): written here = what QML types. Public surface *is* Qt API,
// follows Qt convention. Else QML reads `model.set_read(...)` and
// `onConnection_tested`.
#![allow(non_snake_case)]
// Shipped code held to more than tests; vuo-core's lib.rs says why.
#![cfg_attr(
    not(test),
    deny(
        clippy::string_slice,
        clippy::arithmetic_side_effects,
        clippy::let_underscore_must_use,
        clippy::panic_in_result_fn,
        clippy::unwrap_in_result,
        clippy::get_unwrap
    )
)]
// Panic denials exist because unwinding Rust into Qt C++ frames = UB (§9.5).
// Tests have neither foreign input nor Qt frame above; panicking assert is the
// point.
#![cfg_attr(
    test,
    allow(
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::indexing_slicing
    )
)]
// qmetaobject derive requires QML-invoked methods take `QString` and
// `QVariantList` by value; pedantic `needless_pass_by_value` would ask for
// non-compiling signature. piirit allows it same way.
#![allow(clippy::needless_pass_by_value)]

pub mod arrivals;
pub mod article;
pub mod context;
pub mod memory;
pub mod models;
pub mod settings;
pub mod worker;

use cstr::cstr;
use qmetaobject::qml_register_type;

/// Register Vuo's types with QML engine.
///
/// Call once before loading QML. Safe from Sailfish `main` owning
/// `QApplication`: touches no engine.
pub fn register_qml_types() {
    qml_register_type::<models::EntryModel>(cstr!("Vuo"), 1, 0, cstr!("EntryModel"));
    qml_register_type::<models::FeedModel>(cstr!("Vuo"), 1, 0, cstr!("FeedModel"));
    qml_register_type::<article::ArticleModel>(cstr!("Vuo"), 1, 0, cstr!("ArticleModel"));
    qml_register_type::<settings::Settings>(cstr!("Vuo"), 1, 0, cstr!("Settings"));
    qml_register_type::<arrivals::Arrivals>(cstr!("Vuo"), 1, 0, cstr!("Arrivals"));
}

/// C ABI entry point, for a Sailfish binary whose `main` is C++.
///
/// # Safety
///
/// Must be called from the Qt thread, once, before any QML is loaded.
#[no_mangle]
pub extern "C" fn vuo_register_qml_types() {
    register_qml_types();
}

#[cfg(test)]
mod tests {
    use super::*;
    // For `row_count`. Here, not beside `qml_register_type` above, where
    // non-test build finds it unused.
    use qmetaobject::QAbstractListModel;
    use vuo_core::content::{MediaPolicy, TransformContext};

    /// Offscreen Qt smoke test §8.1 asks for.
    ///
    /// *"Exercises the shim under `QT_QPA_PLATFORM=offscreen` on a headless
    /// runner. Catches model-registration and threading mistakes without a
    /// device."*
    ///
    /// Covers: registering doesn't abort, idempotent (malformed meta-object
    /// aborts process here, not return value; plugin can load more than once).
    ///
    /// CAN'T cover: whether Qt accepted each registration. `qml_register_type`
    /// in qmetaobject 0.2.10 returns `()`, discarding type id (-1 on
    /// rejection). Silent no-op registration caught one level up by
    /// `tests/qml_loads.rs`: QML names type engine lacks, every page fails to
    /// compile. Wrong name caught same way.
    #[test]
    fn types_register_without_a_display() {
        register_qml_types();
        // Registering twice harmless: plugin can load more than once; Qt
        // tolerates re-registration.
        register_qml_types();

        // Each registered type = well-formed QObject, default-constructible
        // (what QML does with `EntryModel {}`).
        assert_eq!(models::EntryModel::default().row_count(), 0);
        assert_eq!(models::FeedModel::default().row_count(), 0);
        assert_eq!(article::ArticleModel::default().row_count(), 0);
        assert_eq!(settings::Settings::default().sync_interval_minutes(), None);
        let _ = arrivals::Arrivals::default();
    }

    #[test]
    fn an_article_model_transforms_and_exposes_blocks() {
        let mut model = article::ArticleModel::default();
        let instance = url::Url::parse("https://miniflux.example/").unwrap();
        let ctx = TransformContext {
            media: MediaPolicy::ProxyThroughInstance {
                instance: instance.clone(),
                extra_trusted: Vec::new(),
                fallback: vuo_core::content::UnproxiedMedia::Strict,
            },
            ..TransformContext::new(instance)
        };

        model.set_html(
            "<h2>Title</h2><p>Body with <b>bold</b> and a <a href=\"javascript:alert(1)\">bad link</a>.</p>",
            &ctx,
        );

        assert_eq!(model.rows().len(), 2);
        let heading = model.rows().first().expect("heading");
        assert_eq!(heading.kind, "heading");
        assert_eq!(heading.level, 2);

        let body = model.rows().get(1).expect("paragraph");
        assert!(
            body.text.contains("<b>bold</b>"),
            "styling should survive: {}",
            body.text
        );
        assert!(
            !body.text.contains("javascript:"),
            "a dangerous href must never reach QML: {}",
            body.text
        );
        assert!(
            body.text.contains("bad link"),
            "but its text is still readable"
        );
    }

    #[test]
    fn hostile_markup_reaches_qml_escaped() {
        let mut model = article::ArticleModel::default();
        let instance = url::Url::parse("https://miniflux.example/").unwrap();
        let ctx = TransformContext::new(instance);
        model.set_html("<p>&lt;img src=x onerror=alert(1)&gt;</p>", &ctx);

        let row = model.rows().first().expect("a paragraph");
        assert!(
            !row.text.contains("<img"),
            "unescaped markup reached the UI: {}",
            row.text
        );
        assert!(
            row.text.contains("&lt;img"),
            "the text itself should still be shown"
        );
    }

    #[test]
    fn un_proxied_images_are_flagged_rather_than_silently_dropped() {
        let mut model = article::ArticleModel::default();
        let instance = url::Url::parse("https://miniflux.example/").unwrap();
        let ctx = TransformContext {
            base_url: url::Url::parse("https://blog.example/post/").ok(),
            ..TransformContext::new(instance)
        };
        model.set_html(
            "<p><img src=\"https://tracker.example/p.gif\" alt=\"x\"></p>",
            &ctx,
        );

        let image = model
            .rows()
            .iter()
            .find(|r| r.kind == "image")
            .expect("an image row");
        assert!(
            image.needs_consent,
            "the UI must ask before leaking the device IP"
        );
        assert_eq!(model.blockedImages, 1);
    }

    #[test]
    fn truncation_is_reported_to_the_ui() {
        let mut model = article::ArticleModel::default();
        let instance = url::Url::parse("https://miniflux.example/").unwrap();
        let mut ctx = TransformContext::new(instance);
        ctx.limits.max_blocks = 5;
        model.set_html(&"<p>x</p>".repeat(50), &ctx);
        assert!(
            model.truncated,
            "a silent truncation reads as 'this is the whole article'"
        );
    }

    #[test]
    fn a_model_with_no_database_does_not_panic() {
        // QML instantiates these before Rust attaches mirror.
        let mut model = models::EntryModel::default();
        model.reload();
        assert_eq!(model.rows().len(), 0);
    }
}
